const originalSelections=new Set();
function languageText(e,field){if(e.type!=='news'||originalSelections.has(e.id))return e[field]||'';return e[field+'Zh']??(liveData?.translation?.status==='rate_limited'?(field==='title'?'中文翻译暂时限流':'翻译服务限流，稍后自动重试；可点击“显示原文”阅读。'):(field==='title'?'正在生成中文译文…':'译文暂未就绪，可点击“显示原文”查看原始内容。'))}
const priorCard=eventCard;
eventCard=function(e){const localized={...e,title:languageText(e,'title'),summary:readingExcerpt(languageText(e,'summary'),e)};let html=priorCard(localized);if(e.progressCandidates?.length)html=html.replace('<div class="event-bottom">',`<div class="event-bottom"><span class="tag high">后续进展候选 ${e.progressCandidates.length}</span>`);if(e.clusterSize>1)html=html.replace('<div class="event-bottom">',`<div class="event-bottom"><span class="tag">${e.clusterSize} 条相关报道 · 已合并</span>`);if(e.type==='news')html=html.replace('<div class="event-bottom">',`<div class="event-bottom"><button class="language-toggle" data-original="${e.id}">${originalSelections.has(e.id)?'显示中文':'显示原文'}</button>`);return html};
const priorDetail=openDetail;
openDetail=function(id){priorDetail(id);const e=events.find(x=>x.id===id);if(!e||e.type!=='news')return;$('#detail-content h1').textContent=languageText(e,'title');$('#detail-content .dialog-inner > p').textContent=languageText(e,'summary');const b=document.createElement('button');b.className='language-toggle';b.dataset.original=id;b.textContent=originalSelections.has(id)?'显示中文':'显示原文';$('#detail-content h1').before(b);if(e.channel==='team'){const info=document.createElement('p');info.className='evidence';info.textContent=e.authorRole+' · 团队成员个人表述，未经独立核实';$('#detail-content h1').before(info)}};
async function postAPI(path,payload){const res=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const d=await res.json();if(!res.ok)throw Error(d.error||'请求失败');return d}
openAdd=function(){showForm(`${formTitle('新增关注项目')}<p>输入项目名称或代币符号，选择结果后确认官方信息。也可以手动填写。</p><form id="discover-form"><label class="field">项目名称 / 代币符号<input name="query" required minlength="2" placeholder="例如 Arbitrum、ARB" autocomplete="off"></label><div class="modal-footer"><button type="button" class="secondary" data-manual-project>手动添加</button><button class="primary" type="submit">搜索项目</button></div></form><div id="discover-results" role="status"></div>`);$('#discover-form').addEventListener('submit',async e=>{e.preventDefault();const q=new FormData(e.target).get('query');const target=$('#discover-results');target.textContent='正在搜索…';try{const r=await fetch('/api/projects/search?q='+encodeURIComponent(q));const data=await r.json();if(!r.ok)throw Error(data.error);target.innerHTML=(data.candidates||[]).map(p=>`<button class="candidate" data-prepare-project="${escapeHtml(p.coinId)}"><span><strong>${escapeHtml(p.name)}</strong><small>${escapeHtml(p.symbol)} · ${p.rank?'市值排名 '+p.rank:'排名未提供'}</small></span><b>选择 →</b></button>`).join('')||'<p>暂无匹配结果，可手动填写。</p>'}catch(err){target.textContent=err.message}})};
function projectForm(p={}){showForm(`${formTitle('确认项目信息')}<p>核对同名代币、官网和官方账号。添加后后台开始采集；没有 Binance 永续交易对的项目仍可查看资讯。</p><form id="new-project-form"><input type="hidden" name="coinId" value="${escapeHtml(p.coinId||'')}"><label class="field">项目名称<input name="name" required maxlength="100" value="${escapeHtml(p.name||'')}"></label><div class="form-grid"><label class="field">代币符号<input name="symbol" required pattern="[A-Za-z0-9]{1,20}" value="${escapeHtml(p.symbol||'')}"></label><label class="field">官方 X 账号<input name="account" pattern="@?[A-Za-z0-9_]{1,15}" value="${escapeHtml(p.account||'')}" placeholder="@username"></label></div><label class="field">官方网站<input name="website" type="url" value="${escapeHtml(p.website||'')}" placeholder="https://"></label><label class="field">RootData 项目页（可选）<input name="rootdataUrl" type="url" placeholder="https://www.rootdata.com/projects/detail/…"></label><div class="evidence">${escapeHtml(p.identity||'手动信息由你确认；系统不会把未核实账号当作已验证官方。')}</div><p id="project-error" role="status"></p><div class="modal-footer"><button type="button" class="secondary" data-close>取消</button><button class="primary" type="submit">添加并开始采集</button></div></form>`);$('#new-project-form').addEventListener('submit',async e=>{e.preventDefault();const button=e.target.querySelector('[type=submit]');button.disabled=true;$('#project-error').textContent='正在保存…';try{const d=await postAPI('/api/projects',Object.fromEntries(new FormData(e.target)));await refreshLive();state.project=d.project.id;state.view='feed';state.filter='all';state.query='';newsSource='all';$('#news-source').value='all';persist();$('#form-dialog').close();render();toast('项目已添加，后台开始采集')}catch(err){$('#project-error').textContent=err.message;button.disabled=false}})}
function candleChart(rows){if(!rows?.length)return '<div class="empty">正在获取 K 线；无对应 Binance 永续合约时无法显示。</div>';const data=rows.slice(-60);const lo=Math.min(...data.map(d=>d.low)),hi=Math.max(...data.map(d=>d.high));const pad=(hi-lo)*.08||1;const min=lo-pad,max=hi+pad,W=900,H=260,left=14,right=82,top=20,bottom=32;const step=(W-left-right)/data.length;const y=v=>top+(max-v)/(max-min)*(H-top-bottom);let chart='';for(let i=0;i<5;i++){const v=min+(max-min)*i/4;chart+=`<line x1="${left}" x2="${W-right}" y1="${y(v)}" y2="${y(v)}" stroke="#e5eae7"/><text x="${W-right+10}" y="${y(v)+4}" fill="#7a858c" font-size="12">${number(v)}</text>`}chart+=data.map((d,i)=>{const x=left+step*(i+.5),up=d.close>=d.open,c=up?'#38846b':'#bc6b65';return `<g><title>${formatTime(d.time)} 开 ${number(d.open)} 高 ${number(d.high)} 低 ${number(d.low)} 收 ${number(d.close)}</title><line x1="${x}" x2="${x}" y1="${y(d.high)}" y2="${y(d.low)}" stroke="${c}"/><rect x="${x-step*.29}" y="${Math.min(y(d.open),y(d.close))}" width="${step*.58}" height="${Math.max(1,Math.abs(y(d.open)-y(d.close)))}" fill="${c}"/></g>`}).join('');chart+=`<text x="14" y="250" font-size="12" fill="#7a858c">${formatTime(data[0].time)}</text><text x="${W-right}" y="250" text-anchor="end" font-size="12" fill="#7a858c">${formatTime(data.at(-1).time)}</text>`;return `<svg class="candles" viewBox="0 0 ${W} ${H}" role="img" aria-label="最近 60 根已收盘四小时 K 线，绿色上涨，红色下跌"><title>Binance 永续 · 4 小时 K 线</title>${chart}</svg>`}
function projectPage(p){const m=liveData?.markets[p.id],social=liveData?.social?.[p.id];return `<section class="project-head"><div>${token(p)}<div><h2>${escapeHtml(p.name)} <span>${p.symbol}</span></h2><p>${escapeHtml(p.identity||'已配置项目 · 官方来源可独立核对')}</p></div></div><div class="official-links">${p.website?`<a href="${escapeHtml(safeUrl(p.website))}" target="_blank" rel="noopener noreferrer">官方网站 ↗</a>`:'<span>官网待补充</span>'}${p.account?`<a href="https://x.com/${p.account.slice(1)}" target="_blank" rel="noopener noreferrer">${p.account} ↗</a>${p.accountProfile?`<span class="module-note">账号资料：${formatTime(p.accountProfile.checkedAt)}${p.accountProfile.status==='error'?' · 查询失败，保留旧资料':''}</span>`:''}`:'<span>官方账号待补充</span>'}<button class="primary" data-action="rule">配置提醒</button></div></section><section class="project-section"><div class="project-section-title"><h3>价格走势</h3><span>Binance ${p.symbol}USDT 永续 · 4 小时 · 已收盘</span></div><div class="chart-price">${m?.price?'$'+number(m.price):'—'} <small>${pct(m?.change24h)} / 24h</small></div>${candleChart(m?.candles)}<div class="chart-meta">EMA 200：${number(m?.ema200)}　EMA 360：${number(m?.ema360)}　最近采集：${formatTime(m?.fetchedAt)}</div></section><section class="project-section"><div class="project-section-title"><h3>团队成员的 X 账号</h3>${p.teamSourceUrl?`<a class="evidence-link" href="${escapeHtml(safeUrl(p.teamSourceUrl))}" target="_blank" rel="noopener noreferrer">RootData 团队资料 ↗</a>`:''}<button class="text-button" data-rootdata-project="${p.id}">关联 RootData</button><button class="text-button" data-add-team="${p.id}">＋ 补充账号</button></div><div class="account-grid">${(p.team||[]).map(a=>`<article class="account-card"><a target="_blank" rel="noopener noreferrer" href="https://x.com/${escapeHtml(a.account)}">@${escapeHtml(a.account)} ↗</a><p>${escapeHtml(a.role)}</p><small>${escapeHtml(a.identity)}</small><a class="evidence-link" target="_blank" rel="noopener noreferrer" href="${escapeHtml(safeUrl(a.evidence))}">${a.source==='RootData'?'RootData 人物资料':'查看身份依据'} ↗</a>${a.rootdataEvidence?`<a class="evidence-link" href="${escapeHtml(safeUrl(a.rootdataEvidence))}" target="_blank" rel="noopener noreferrer">RootData 资料 ↗</a><small>核对日期：${escapeHtml(a.rootdataCheckedAt)}</small>`:''}</article>`).join('')||'<p class="module-empty">暂未找到有充分依据的团队账号。可以补充账号及身份依据，系统不会用关注关系推断团队身份。</p>'}</div></section><section class="project-section"><div class="project-section-title"><h3>近期讨论者 / KOL</h3><span>近 7 天 · 粉丝 ≥ 2 万</span></div><p class="module-note">按检索样本的持续讨论、内容形式和推广关键词排序；不代表可信度或全网排名。</p><p class="module-note">${social?.lastSuccessAt||social?.updatedAt?'最近成功：'+formatTime(social.lastSuccessAt||social.updatedAt):'尚未成功获取'}${social?.stale?' · 本次查询失败，保留上次结果':''}</p><div class="account-grid">${(social?.discussants||[]).map((a,i)=>`<article class="account-card"><a target="_blank" rel="noopener noreferrer" href="https://x.com/${escapeHtml(a.account)}">@${escapeHtml(a.account)} ↗</a><small>${Number(a.followers).toLocaleString('zh-CN')} 位粉丝 · ${formatTime(a.publishedAt)} · ${a.count} 条匹配内容</small>${a.quality?`<small>${escapeHtml(a.quality.basis)}</small><small>${escapeHtml(a.quality.limit)}</small>`:``}<p class="discussion-text" id="discussion-${i}">${escapeHtml(a.textZh||'中文译文生成中，可查看原帖。')}</p><a class="evidence-link" target="_blank" rel="noopener noreferrer" href="${escapeHtml(safeUrl(a.url))}">查看相关推文 ↗</a><button class="language-toggle" data-discussion="${i}">显示原文</button></article>`).join('')||`<p class="module-empty">${social?.status==='ok'?'本次检索暂无粉丝数达到 2 万的近期讨论者。':social?.status==='error'?'账号查询暂不可用，稍后重试。':'正在发现近期讨论者…'}</p>`}</div></section><div class="project-section-title news-divider"><h3>项目动态</h3><span>消息与市场信号</span></div>`}
const priorProjectRender=render;
render=function(){priorProjectRender();const p=catalog.find(x=>x.id===state.project);if(p){$('#project-overview').innerHTML=projectPage(p);compactAccounts(p)}};
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(d.original){const id=Number(d.original);originalSelections.has(id)?originalSelections.delete(id):originalSelections.add(id);const opened=$('#detail-dialog').open;render();if(opened){$('#detail-dialog').close();openDetail(id)}}if(d.manualProject!==undefined)projectForm();if(d.prepareProject){b.disabled=true;try{const p=await postAPI('/api/projects/prepare',{coinId:d.prepareProject});projectForm(p)}catch(err){toast(err.message);b.disabled=false}}if(d.discussion!==undefined){const a=liveData.social[state.project].discussants[Number(d.discussion)];const show=b.textContent==='显示原文';$('#discussion-'+d.discussion).textContent=show?a.text:(a.textZh||'中文译文生成中');b.textContent=show?'显示中文':'显示原文'}if(d.addTeam){showForm(`${formTitle('补充团队账号')}<p>请提供能说明身份的官网介绍或官方声明链接。新增账号会标为“待核实”。</p><form id="team-form"><label class="field">X 账号<input name="account" required pattern="@?[A-Za-z0-9_]{1,15}" placeholder="@username"></label><label class="field">身份 / 职位<input name="role" required maxlength="80"></label><label class="field">身份依据链接<input name="evidence" type="url" required placeholder="https://"></label><p id="team-error"></p><div class="modal-footer"><button class="primary" type="submit">保存账号</button></div></form>`);$('#team-form').addEventListener('submit',async ev=>{ev.preventDefault();try{await postAPI('/api/projects/team',{...Object.fromEntries(new FormData(ev.target)),projectId:d.addTeam});await refreshLive();$('#form-dialog').close();render()}catch(err){$('#team-error').textContent=err.message}})}});
render();

function compactAccounts(p){
 const teamSection=document.querySelectorAll('#project-overview .account-grid')[0]?.closest('.project-section');
 const observation=p.rootdataObservation;
 if(teamSection&&observation){
  const note=document.createElement('p');note.className='module-note';note.textContent='RootData 公开团队区：'+(observation.status==='ok'?'最近读取 '+formatTime(observation.checkedAt):'查询失败；最近成功 '+formatTime(observation.checkedAt))+'。仅公开可见范围，未出现不代表离职。';teamSection.append(note);
  if(observation.candidates?.length){const details=document.createElement('details');details.className='related-report';const summary=document.createElement('summary');summary.textContent=observation.candidates.length+' 位公开团队人物待补齐账号';details.append(summary);for(const person of observation.candidates){const link=document.createElement('a');link.className='evidence-link';link.href=safeUrl(person.url);link.target='_blank';link.rel='noopener noreferrer';link.textContent=person.name+' · 核对资料 ↗';details.append(link);const check=observation.accountChecks?.find(c=>c.name===person.name);if(check?.message){const reason=document.createElement('small');reason.textContent=check.message;details.append(reason)}}teamSection.append(details)}
 }

 const groups=document.querySelectorAll('#project-overview .account-grid');
 groups.forEach((group,groupIndex)=>{
  const accounts=groupIndex===0?(p.team||[]):(liveData?.social?.[p.id]?.discussants||[]);
  group.querySelectorAll('.account-card').forEach((card,i)=>{
   const a=accounts[i];if(!a)return;
   if(a.profile){const note=document.createElement('small');note.textContent='账号资料采集：'+formatTime(a.profile.checkedAt)+(a.profile.status==='error'?' · 查询失败，保留旧资料':'')+'。不代表任职核验。';card.append(note);const last=a.profile.history?.at(-1);if(last){const changes=document.createElement('small');changes.textContent='最近变化：'+last.fields.join('、')+' · '+formatTime(last.at);card.append(changes)}}
   const item=document.createElement('div');item.className='avatar-item';
   const button=document.createElement('button');button.className='account-avatar';button.type='button';
   button.setAttribute('aria-label','查看 @'+a.account+' 的信息');button.setAttribute('aria-expanded','false');
   const panelId='account-popover-'+groupIndex+'-'+i;button.setAttribute('aria-controls',panelId);
   const fallback=document.createElement('span');fallback.textContent=a.account.slice(0,2).toUpperCase();button.append(fallback);
   const avatar=a.avatar||a.profileImageUrl;
   if(avatar&&/^https:\/\/pbs\.twimg\.com\//.test(avatar)){const img=document.createElement('img');img.src=avatar;img.alt='';img.loading='lazy';img.addEventListener('error',()=>img.remove());button.append(img)}
   card.before(item);item.append(button,card);card.id=panelId;card.classList.add('account-popover');card.setAttribute('role','region');card.setAttribute('aria-label','@'+a.account+' 的信息');
   let timer;
   const close=()=>{item.classList.remove('is-open');button.setAttribute('aria-expanded','false')};
   const open=()=>{clearTimeout(timer);document.querySelectorAll('.avatar-item.is-open').forEach(other=>{if(other!==item){other.classList.remove('is-open');other.querySelector('button').setAttribute('aria-expanded','false')}});item.classList.add('is-open');button.setAttribute('aria-expanded','true');const r=button.getBoundingClientRect();const w=Math.min(300,window.innerWidth-24);card.style.width=w+'px';card.style.left=Math.max(12,Math.min(r.left,window.innerWidth-w-12))+'px';const h=card.offsetHeight;card.style.top=(r.bottom+h+10<window.innerHeight?r.bottom+8:Math.max(12,r.top-h-8))+'px'};
   item.addEventListener('mouseenter',open);item.addEventListener('mouseleave',()=>{timer=setTimeout(close,160)});
   item.addEventListener('focusin',open);item.addEventListener('focusout',e=>{if(!item.contains(e.relatedTarget))close()});
   button.addEventListener('click',()=>open());item.addEventListener('keydown',e=>{if(e.key==='Escape'){close();button.blur()}});
  });
 });
}
document.addEventListener('click',e=>{if(!e.target.closest('.avatar-item'))document.querySelectorAll('.avatar-item.is-open').forEach(item=>{item.classList.remove('is-open');item.querySelector('button').setAttribute('aria-expanded','false')})});
window.addEventListener('scroll',()=>document.querySelectorAll('.avatar-item.is-open').forEach(item=>{item.classList.remove('is-open');item.querySelector('button').setAttribute('aria-expanded','false')}),{passive:true});

function readingExcerpt(text,e){
 if(e.type!=='news'||originalSelections.has(e.id))return text;
 const clean=text.replace(/https?:\/\/\S+/g,'').replace(/\s+/g,' ').trim();
 if(clean.length<=150)return clean;
 const boundary=clean.slice(30,150).search(/[。！？]/);
 return clean.slice(0,boundary>=0?boundary+31:150)+(boundary>=0?'':'…');
}

const beforeClusterDetail=openDetail;
openDetail=function(id){beforeClusterDetail(id);const e=events.find(x=>x.id===id);if(!e?.relatedItems)return;const section=document.createElement('section');section.className='quality-evidence';section.innerHTML=(e.progressCandidates?.length?'<h3>后续进展候选</h3>'+e.progressCandidates.map(u=>`<div class="evidence">${formatTime(u.publishedAt)} · ${escapeHtml(u.source)}<br>新增表述：${escapeHtml(u.signals.join('、'))}<br>${escapeHtml(u.reason)}<br><a class="evidence-link" href="${escapeHtml(safeUrl(u.url))}" target="_blank" rel="noopener noreferrer">核对原文 ↗</a></div>`).join(''):'')+'<h3>相关报道与各方表述</h3><p class="module-note">'+escapeHtml(e.clusterReason)+'</p>'+e.relatedItems.map(item=>`<details class="related-report"><summary>${escapeHtml(item.source)} · ${escapeHtml(formatTime(item.publishedAt))}</summary><p>${escapeHtml(originalSelections.has(id)?item.summary:(item.summaryZh||'中文译文生成中，可查看原文'))}</p><small>${escapeHtml(item.clusterReason||'最早收录的报道')}</small><a class="evidence-link" href="${escapeHtml(safeUrl(item.url))}" target="_blank" rel="noopener noreferrer">查看原文 ↗</a></details>`).join('');$('#detail-content .modal-footer').before(section)};

document.addEventListener('click',e=>{
 const b=e.target.closest('[data-rootdata-project]');if(!b)return;
 const p=catalog.find(p=>p.id===b.dataset.rootdataProject);
 showForm(`${formTitle('关联 RootData 团队资料')}<p>填写该项目详情页。系统会校验页面中的 X 链接与 ${escapeHtml(p.account||'已配置账号')} 一致，然后读取公开团队区。</p><form id="rootdata-source-form"><label class="field">RootData 项目页<input type="url" name="url" required value="${escapeHtml(p.teamSourceUrl||'')}" placeholder="https://www.rootdata.com/projects/detail/…"></label><p id="rootdata-source-error" role="status"></p><div class="modal-footer"><button type="button" class="secondary" data-close>取消</button><button class="primary">校验并关联</button></div></form>`);
 $('#rootdata-source-form').addEventListener('submit',async event=>{event.preventDefault();const button=event.target.querySelector('.primary');button.disabled=true;$('#rootdata-source-error').textContent='正在核对官方账号…';try{await postAPI('/api/projects/rootdata',{projectId:p.id,url:new FormData(event.target).get('url')});await refreshLive();$('#form-dialog').close();toast('已关联，后台正在补齐团队资料')}catch(error){$('#rootdata-source-error').textContent=error.message;button.disabled=false}});
});
